export const alphabet=['Alpha','Bravo','Charlie','Delta','Echo','Foxtrot','Golf','Hotel','India','Juliett','Kilo','Lima','Mike','November','Oscar','Papa','Quebec','Romeo','Sierra','Tango','Uniform','Victor','Whiskey','X-ray','Yankee','Zulu'];
export const fields={
 info:{label:'ATIS information',type:'info'},qnh:{label:'QNH (hPa)',type:'qnh',placeholder:'e.g. 1023'},
 sid:{label:'Assigned departure / SID',placeholder:'As cleared by ATC'},squawk:{label:'Assigned squawk',placeholder:'Four digits, 0–7',type:'squawk'},initialLevel:{label:'Initial cleared altitude / level',placeholder:'e.g. 6,000 feet'},departureRunway:{label:'Departure runway',placeholder:'e.g. 27R',type:'runway',airport:'departure'},
 facing:{label:'Pushback facing direction',placeholder:'e.g. west'},holding:{label:'Departure holding point',placeholder:'e.g. A1'},taxiOut:{label:'Departure taxi route',placeholder:'e.g. A, A1'},
 currentLevel:{label:'Current altitude / flight level',placeholder:'e.g. flight level 350'},climbLevel:{label:'Cleared climb altitude / level',placeholder:'e.g. flight level 150'},waypoint:{label:'Inbound waypoint',placeholder:'As shown on your route'},direct:{label:'New direct-to waypoint',placeholder:'If assigned by ATC'},descentLevel:{label:'Cleared descent altitude / level',placeholder:'e.g. flight level 100'},
 arrivalInfo:{label:'Arrival ATIS information',type:'info'},arrivalQnh:{label:'Arrival QNH (hPa)',type:'qnh',placeholder:'From the arrival ATIS'},arrivalRunway:{label:'Arrival runway',placeholder:'e.g. 27L',type:'runway',airport:'arrival'},approachType:{label:'Cleared approach type',placeholder:'e.g. ILS, RNAV, visual'},exit:{label:'Runway exit / current holding point',placeholder:'e.g. B4'},arrivalStand:{label:'Assigned arrival stand',placeholder:'e.g. 214'},taxiIn:{label:'Arrival taxi route',placeholder:'e.g. B, C, D'}
};
const card=(role,title,text)=>({role,title,text});
export const steps=[
 {id:'atis',name:'ATIS',phase:'Before departure',title:'Listen first. Then check in.',description:'Listen to the departure ATIS to get the current information letter and QNH. Enter both below before proceeding.',fields:['info','qnh','departureRunway'],cards:[card('note','Before you move on','Set your altimeter to the reported QNH. The runway field is optional until a runway has been assigned or confirmed.')]},
 {id:'delivery',name:'Delivery',phase:'Departure',title:'Request your IFR clearance.',description:'Use your flight details below. Record the clearance you actually receive, then read it back.',fields:['sid','squawk','initialLevel','departureRunway'],cards:[card('pilot','Request clearance','{{callsign}}, at stand {{stand}}, aircraft type {{aircraft}}, requesting IFR clearance to {{destination}}, with information {{info}}, QNH {{qnh}}.'),card('atc','Clearance example','{{callsign}}, cleared to {{destination}} via {{sid}} departure, climb to {{initialLevel}}, squawk {{squawk}}.'),card('pilot','Read back your clearance','Cleared to {{destination}} via {{sid}} departure, climb to {{initialLevel}}, squawk {{squawk}}, {{callsign}}.')]},
 {id:'ground-out',name:'Ground',phase:'Departure',title:'Push, start, and taxi.',description:'Request pushback first. Once ready to move, request taxi and record the route assigned by the controller.',fields:['facing','holding','taxiOut','departureRunway'],cards:[card('pilot','Request push and start','{{callsign}}, at stand {{stand}}, requesting push and start.'),card('atc','Pushback example','{{callsign}}, push and start approved, facing {{facing}}.'),card('pilot','Pushback readback','Push and start approved, facing {{facing}}, {{callsign}}.'),card('pilot','Request taxi','{{callsign}}, pushed back from stand {{stand}}, requesting taxi.'),card('atc','Taxi example','{{callsign}}, taxi to holding point {{holding}}, runway {{departureRunway}}, via {{taxiOut}}.'),card('pilot','Taxi readback','Taxi to holding point {{holding}}, runway {{departureRunway}}, via {{taxiOut}}, {{callsign}}.')]},
 {id:'tower-out',name:'Tower',phase:'Departure',title:'From holding point to takeoff.',description:'Contact Tower when instructed. Line-up clearance and takeoff clearance are separate instructions.',fields:['holding','departureRunway'],cards:[card('pilot','Initial contact','{{callsign}}, taxiing to holding point {{holding}}, runway {{departureRunway}}.'),card('atc','Line-up example','{{callsign}}, line up and wait, runway {{departureRunway}}.'),card('pilot','Line-up readback','Line up and wait, runway {{departureRunway}}, {{callsign}}.'),card('atc','Takeoff example','{{callsign}}, runway {{departureRunway}}, cleared for takeoff.'),card('pilot','Takeoff readback','Runway {{departureRunway}}, cleared for takeoff, {{callsign}}.')]},
 {id:'departure',name:'Departure / Approach',phase:'Climb',title:'Check in on the climb.',description:'After takeoff, use the Departure or Approach controller you are handed to. Update your actual altitude and cleared level.',fields:['currentLevel','climbLevel'],cards:[card('pilot','Initial contact','{{callsign}}, passing {{currentLevel}}, climbing to {{climbLevel}}.'),card('atc','Climb example','{{callsign}}, identified, climb to {{climbLevel}}.'),card('pilot','Climb readback','Climb to {{climbLevel}}, {{callsign}}.')]},
 {id:'centre',name:'Centre',phase:'En route',title:'Cruise and prepare to descend.',description:'Update your level and inbound waypoint. A direct-to instruction may be issued for traffic or routing; enter it only if assigned.',fields:['currentLevel','waypoint','direct','descentLevel'],cards:[card('pilot','Initial contact','{{callsign}}, with you at {{currentLevel}}, inbound {{waypoint}}.'),card('atc','Identification example','{{callsign}}, identified.'),card('atc','Optional direct-to example','{{callsign}}, identified, proceed direct {{direct}}.'),card('pilot','Direct-to readback','Direct {{direct}}, {{callsign}}.'),card('pilot','Approaching top of descent','{{callsign}}, approaching top of descent.'),card('atc','Descent example','{{callsign}}, descend to {{descentLevel}}.'),card('pilot','Descent readback','Descend to {{descentLevel}}, {{callsign}}.')]},
 {id:'approach',name:'Approach',phase:'Arrival',title:'Set up for the arrival.',description:'Listen to the destination ATIS. Enter the arrival information and QNH separately from your departure, then record your assigned approach.',fields:['currentLevel','descentLevel','arrivalInfo','arrivalQnh','arrivalRunway','approachType'],cards:[card('pilot','Initial contact','{{callsign}}, at {{currentLevel}}, descending to {{descentLevel}}, with information {{arrivalInfo}}, QNH {{arrivalQnh}}.'),card('atc','Approach clearance example','{{callsign}}, cleared {{approachType}} approach, runway {{arrivalRunway}}.'),card('pilot','Approach readback','Cleared {{approachType}} approach, runway {{arrivalRunway}}, {{callsign}}.')]},
 {id:'tower-in',name:'Tower',phase:'Arrival',title:'Final approach and landing.',description:'Use the arrival runway confirmed by ATC. After landing, follow the controller’s exit instructions and consult your airport chart.',fields:['arrivalRunway','exit'],cards:[card('pilot','On final','{{callsign}}, with you on final, runway {{arrivalRunway}}.'),card('atc','Landing example','{{callsign}}, runway {{arrivalRunway}}, cleared to land.'),card('pilot','Landing readback','Runway {{arrivalRunway}}, cleared to land, {{callsign}}.'),card('note','After landing','The controller may specify an exit taxiway and direction. Vacate as instructed and keep your airport chart available.')]},
 {id:'ground-in',name:'Ground',phase:'Arrival',title:'Taxi to your arrival stand.',description:'Once you have vacated the runway, contact Ground when instructed. Use the arrival stand assigned to you.',fields:['exit','arrivalStand','taxiIn'],cards:[card('pilot','Request taxi','{{callsign}}, runway vacated at {{exit}}, requesting taxi.'),card('atc','Taxi-to-stand example','{{callsign}}, taxi to stand {{arrivalStand}} via {{taxiIn}}.'),card('pilot','Taxi readback','Taxi to stand {{arrivalStand}} via {{taxiIn}}, {{callsign}}.')]}];
export function flightKey(flight){return JSON.stringify([flight.airline,flight.flightNumber,flight.departure,flight.arrival,flight.aircraft,flight.customAircraft,flight.gate]);}
export function validFlight(f){return !!f&&/^[A-Z]{3}$/.test(f.airline)&&/^\d{1,4}$/.test(f.flightNumber)&&/^[A-Z]{4}$/.test(f.departure)&&/^[A-Z]{4}$/.test(f.arrival)&&/^[A-Z0-9]{2,4}$/.test(f.aircraft==='OTHER'?f.customAircraft:f.aircraft)&&typeof f.gate==='string'&&!!f.gate.trim();}
export function fieldError(key,value){
 if(!value)return '';
 if(fields[key]?.type==='info'&&!alphabet.includes(value))return 'Choose an information letter.';
 if(fields[key]?.type==='qnh'&&(!/^\d{3,4}$/.test(value)||Number(value)<850||Number(value)>1100))return 'Enter QNH in hPa, between 850 and 1100.';
 if(fields[key]?.type==='squawk'&&!/^[0-7]{4}$/.test(value))return 'Use four digits, each from 0 to 7.';
 if(fields[key]?.type==='runway'&&!/^(0[1-9]|[12]\d|3[0-6])[LRC]?$/.test(value))return 'Use a runway number such as 09, 27L or 36.';
 return '';
}
export function atisReady(values){return alphabet.includes(values.info)&&!!values.qnh&&!fieldError('qnh',values.qnh);}
export function phraseParts(template,values){return template.split(/(\{\{\w+\}\})/g).filter(Boolean).map(text=>{const match=text.match(/^\{\{(\w+)\}\}$/);if(!match)return {text};const key=match[1];return values[key]?{text:String(values[key]),key}:{text:fields[key]?.label||({destination:'Destination airport name',aircraft:'Aircraft type',stand:'Departure stand',callsign:'Callsign'}[key]||key),key,missing:true};});}
